CREATE PROCEDURE SP_ConsultaFacturaSinHash		/*---------------------Parametros contrato---------------------*/	@IdContrato INT = NULL,	@IdUsuario INT = NULL,	@FechaRegistro DATETIME = NULL		/*---------------------Parametros contrato---------------------*/ASBEGIN	SELECT 	FI.IdFactura,	ISNULL(FI.IdContrato, P.IdContrato)  AS IdContrato,	--FI.IdContrato,	FI.XML, 	FI.CreadoPor, 	FI.FechaRecepcion	FROM dbo.MM_AceptacionFactura AS AFI 	LEFT JOIN dbo.FI_Factura AS FI ON FI.IdFactura = AFI.IdFactura	LEFT JOIN dbo.MM_AceptacionPedido AS AP ON AP.IdAceptacionPedido = AFI.IdAceptacionPedido	LEFT JOIN dbo.MM_Pedido AS P ON P.IdPedido = AP.IdPedido	WHERE FI.IdEliminado IS NULL		AND XML IS NOT NULL		AND FI.IdFactura NOT IN (SELECT IdFactura FROM dbo.FI_ArchivoXml)END